### STR

Example from libcore:

``` rust
#![crate_type = "lib"]
#![feature(associated_types)]
#![no_implicit_prelude]

trait Iterator {
    type Item;
}

trait AdditiveIterator {
    type Sum;

    fn sum(self) -> Self::Sum;
}

impl<I> AdditiveIterator for I where I: Iterator<Item=u8> {  //~error conflicting implementation
    type Sum = u8;

    fn sum(self) -> u8 { loop {} }
}

impl<I> AdditiveIterator for I where I: Iterator<Item=u16> {  //~note conflicting implementation here
    type Sum = u16;

    fn sum(self) -> u16 { loop {} }
}
```
### Version

7d4f487

No type can implement _both_ `Iterator<Item=u8>` and `Iterator<Item=u16>`, therefore these blanket impls are non overlapping and should be accepted.

cc @nikomatsakis

Feature gate: `#![feature(extract_if)]` (previously `drain_filter`)

This is a tracking issue for `Vec::extract_if` and `LinkedList::extract_if`, which can be used for random deletes using iterators.

### Public API

```rust
pub mod alloc {
    pub mod vec {
        impl<T, A> Vec<T, A>
        where
            A: Allocator,
        {
            pub fn extract_if<F>(&mut self, filter: F) -> ExtractIf<'_, T, F, A>
            where
                F: FnMut(&mut T) -> bool;
        }

        pub struct ExtractIf<'a, T, F, #[unstable(feature = "allocator_api", issue = "32838")] A = Global>
        where
            F: FnMut(&mut T) -> bool,
            A: Allocator;

        impl<T, F, A> Iterator for ExtractIf<'_, T, F, A>
        where
            F: FnMut(&mut T) -> bool,
            A: Allocator;

        impl<T, F, A> Drop for ExtractIf<'_, T, F, A>
        where
            A: Allocator;

        impl<T, F, A> Debug for ExtractIf<'_, T, F, A>
        where
            T: Debug,
            F: Debug,
            A: Debug + Allocator;
    }

    pub mod collections {
        pub mod linked_list {
            impl<T, A> LinkedList<T, A>
            where
                A: Allocator,
            {
                pub fn extract_if<F>(&mut self, filter: F) -> ExtractIf<'_, T, F, A>
                where
                    F: FnMut(&mut T) -> bool;
            }

            pub struct ExtractIf<'a, T, F, #[unstable(feature = "allocator_api", issue = "32838")] A = Global>
            where
                T: 'a,
                F: 'a + FnMut(&mut T) -> bool,
                A: Allocator;

            impl<T, F, A> Iterator for ExtractIf<'_, T, F, A>
            where
                F: FnMut(&mut T) -> bool,
                A: Allocator;

            impl<T, F> Debug for ExtractIf<'_, T, F, Global>
            where
                T: Debug;
        }
    }
}
```

